import {DatabaseSync} from 'node:sqlite';
import fs from 'node:fs';
import path from 'node:path';
/** Schema-only test database. SKCT fixtures are generated by each test. */
export function openSkctTestDatabase(root){
  const database=new DatabaseSync(':memory:');database.exec('PRAGMA foreign_keys=ON');
  const folder=path.join(root,'apps/backend/drizzle');
  for(const name of fs.readdirSync(folder).filter(value=>/^\d{4}_.*\.sql$/u.test(value)).sort())database.exec(fs.readFileSync(path.join(folder,name),'utf8'));
  return database;
}
